content.content:
/* Container
 *
 * Align the contents of the site above the proper threshold with some margin-fu
 * with a 25%-wide `.sidebar`.
 */

.content {
  padding-top:    2rem;
  padding-bottom: 2rem;
}

@media (min-width: 48em) {
  .content {
    max-width: 38rem;
    margin-left: 2rem;
    margin-right: 1.75rem;
  }
}

@media (min-width: 64em) {
  .content {
    max-width: 44rem;
    margin-left: 2rem;
    margin-right: 1.75rem;
  }
}

.footnote {
  font-size: 0.7em;
  margin-top: 0.5rem;
  color: var(--sidebar-p-color);
}

.go {
  color: #444444;
}

.badge {
  display:inline;
  vertical-align: bottom;
}

.badges {
  float: right;
}

.brand {
  font-size: 4.0em;
  margin-bottom: 0;
}

/*
 * Reverse layout
 */
@media (min-width: 48em) {
  .content {
    max-width: 38rem;
    margin-left: 1.75rem;
    margin-right: 2rem;
  }
}

@media (min-width: 64em) {
  .content {
    max-width: 44rem;
    margin-left: 1.75rem;
    margin-right: 2rem;
  }
}

/*
 * Themes
 *
 * As of v1.1, Hyde includes optional themes to color the sidebar and links
 * within blog posts. To use, add the class of your choosing to the `body`.
 */

