1	/*
2	 *  __                  __
3	 * /\ \                /\ \
4	 * \ \ \___   __  __   \_\ \     __
5	 *  \ \  _ `\/\ \/\ \  /'_` \  /'__`\
6	 *   \ \ \ \ \ \ \_\ \/\ \_\ \/\  __/
7	 *    \ \_\ \_\/`____ \ \___,_\ \____\
8	 *     \/_/\/_/`/___/> \/__,_ /\/____/
9	 *                /\___/
10	 *                \/__/
11	 *
12	 * Designed, built, and released under MIT license by @mdo. Learn more at
13	 * https://github.com/poole/hyde.
14	 */
15	
16	
17	/*
18	 * Contents
19	 *
20	 * Global resets
21	 * Sidebar
22	 * Container
23	 * Reverse layout
24	 * Themes
25	 */
26	
27	
28	/*
29	 * Global resets
30	 *
31	 * Update the foundational and global aspects of the page.
32	 */
33	
34	html {
35	  font-family: "Fira Sans", sans-serif;
36	    font-weight:300;
37	
38	}
39	@media (min-width: 48em) {
40	  html {
41	    font-size: 16px;
42	  }
43	}
44	@media (min-width: 58em) {
45	  html {
46	    font-size: 20px;
47	  }
48	}
49	
50	pre {
51	  tab-size:4;
52	}
53	
54	/*
55	 * Sidebar
56	 *
57	 * Flexible banner for housing site name, intro, and "footer" content. Starts
58	 * out above content in mobile and later moves to the side with wider viewports.
59	 */
60	
61	.sidebar {
62	  text-align: center;
63	  padding: 2rem 1rem;
64	  color: rgba(255,255,255,.5);
65	  flex-shrink: 0;
66	}
67	@media (min-width: 48em) {
68	  .sidebar {
69	    top: 0;
70	    left: 0;
71	    bottom: 0;
72	    width: 18rem;
73	    text-align: left;
74	    overflow-y: auto;
75	    scrollbar-width: thin;
76	    scrollbar-color: rgb(70, 70, 70) auto;
77	  }
78	  
79	  ::-webkit-scrollbar {
80	    width: 7px;
81	  }
82	
83	  ::-webkit-scrollbar-track {
84	    background: transparent;
85	    border-radius: 10px;
86	  }
87	
88	  ::-webkit-scrollbar-thumb {
89	    background-color:rgb(70, 70, 70);
90	    border-radius: 10px;
91	  }
92	
93	  
94	  ::-webkit-scrollbar-thumb:hover {
95	    background-color:rgb(150, 150, 150);
96	  }
97	}
98	
99	/* Sidebar links */
100	.sidebar a, li {
101	  color: var(--sidebar-a-color);
102	}
103	
104	/* About section */
105	.sidebar-about {
106	  text-align: center;
107	  color: var(--sidebar-p-color);
108	}
109	.sidebar-about h1 {
110	  color: var(--sidebar-h1-color);
111	  margin-top: 0;
112	  font-weight:300;
113	  font-size: 1.5em;
114	  font-family: "Abril Fatface", serif;
115	}
116	
117	/* Sidebar nav */
118	.sidebar-nav {
119	  margin-top: 2rem;
120	  margin-bottom: 2rem;
121	  padding-left: 0;
122	  list-style: none;
123	}
124	
125	.subnav {
126	 list-style: none;
127	  padding-left: 0;
128	}
129	
130	.sidebar-nav-item {
131	  display: block;
132	}
133	a.sidebar-nav-item:hover,
134	a.sidebar-nav-item:focus {
135	  text-decoration: underline;
136	}
137	.sidebar-nav-item.active {
138	  font-weight: bold;
139	}
140	
141	/* Sticky sidebar
142	 *
143	 * Add the `sidebar-sticky` class to the sidebar's container to affix it the
144	 * contents to the bottom of the sidebar in tablets and up.
145	 */
146	
147	@media (min-width: 48em) {
148	  .sidebar-sticky {
149	    top: 1rem;
150	    width: 16rem;
151	  }
152	}
153	
154	
155	/* Container
156	 *
157	 * Align the contents of the site above the proper threshold with some margin-fu
158	 * with a 25%-wide `.sidebar`.
159	 */
160	
161	.content {
162	  padding-top:    2rem;
163	  padding-bottom: 2rem;
164	}
165	
166	@media (min-width: 48em) {
167	  .content {
168	    max-width: 38rem;
169	    margin-left: 2rem;
170	    margin-right: 1.75rem;
171	  }
172	}
173	
174	@media (min-width: 64em) {
175	  .content {
176	    max-width: 44rem;
177	    margin-left: 2rem;
178	    margin-right: 1.75rem;
179	  }
180	}
181	
182	.footnote {
183	  font-size: 0.7em;
184	  margin-top: 0.5rem;
185	  color: var(--sidebar-p-color);
186	}
