body > .wrapper {
    display: flex;
    height: 100%;
}
.container.content {
    overflow-y: auto;
    flex-grow: 1;
}
.layout-reverse .container.content {
    padding-right: 0;
    padding-left: 2rem;
}
.container.content::-webkit-scrollbar {
   width: 3px;
}
.container.content::-webkit-scrollbar-thumb {
   border-radius: 1.5px;
}
.container.content::-webkit-scrollbar-track {
   margin: 5.5em 0;
}

.sidebar {
    background-color: var(--sidebar-bg-color);
}
.lead {
  text-align: center;
  color: var(--sidebar-p-color);
}
.sidebar-about img {
    margin-left: auto;
    margin-right: auto;
    text-align: center;
    border: 2px solid var(--sidebar-img-border-color);
    border-radius: 50%;
    height: 180px;
    width: 180px;
}
.social {
    margin-right: 0.5em;
    text-decoration: none !important;
    color: var(--sidebar-socials-color) !important;
}
.heading {
    margin-top: 1em;
}
.post-date {
    display: inline-block;
    color: var(--date-color);
}
.info span {
    display: inline-block;
}
.info ul {
    display: inline-block;
    float: right;
}
.info ul li {
    margin-left: 0.5em;
}
.headline {
    display: flex;
    justify-content: space-between;
    align-items: center;
    align-content: center;
}
.reading-time {
    color: gray;
    font-style: italic;
}
.newsletters .help-block-for-success {
    display: none;
    margin: 0.25rem 1rem 0.25rem 0;
    text-align: center;
    color: green;
}
.newsletters .help-block-for-error {
    display: none;
    margin: 0.25rem 1rem 0.25rem 0;
    text-align: center;
    color: #de0928;
}
.newsletters .help-block-show {
    display: block;
}
.newsletters form {
    display: flex;
    align-content: center;
    justify-content: center;
    flex-flow: row wrap;
}
.newsletters .email-subscription-form-hide {
    display: none;
}
.newsletters label {
    margin: 0.25rem 1rem 0.25rem 0;
    text-align: center;
}
.newsletters input {
    margin: 0.25rem 1rem 0.25rem 0;
    font-size: 0.75rem;
    padding: 0.25rem 0.5rem;
    border: 1px solid var(--text-color);
    border-radius: 0.25rem;
}
.newsletters input:focus-visible {
    outline: none;
}
.newsletters button {
    background-color: transparent;
    color: var(--text-color);
    padding: 0.25rem 0.5rem;
    border-radius: 0.25rem;
    border: 1px solid var(--text-color);
    font-family: inherit;
    font-size: 0.85rem;
    cursor: pointer;
    margin: 0.25rem 0;
}
.tags {
    padding-left: 0em;
}
.tags li {
    display: inline;
    text-decoration: none;
}
.tags li a {
    color: var(--table-stripe-color);
    display: inline-block;
    padding: 0em 0.7em;
    text-align: center;
    font-size: 0.7em;
    background-color: var(--list-color);
    border-radius: 0.2em;
}
/* Tables */
table {
  margin-bottom: 1rem;
  width: 100%;
  border: 1px solid var(--table-border-color);
  border-collapse: collapse;
}
td,
th {
  padding: .25rem .5rem;
  border: 1px solid var(--table-border-color);
}
tbody tr:nth-child(odd) td,
tbody tr:nth-child(odd) th {
  background-color: var(--table-stripe-color);
}

.entries li {
    display: flex;
}
.entries li .title {
    order: 1;
}
.entries li .published {
    order: 3;
}
.entries li::after {
    background-image: radial-gradient(circle, currentcolor 1px, transparent 1.5px);
    background-position: bottom;
    background-size: 1ex 3.5px;
    background-repeat: space no-repeat;
    content: "";
    flex-grow: 1;
    height: 1.1em;
    order: 2;
}
.article-toc {
    display: none;
    font-size: 0.9em;
    width: 20em;
    margin-top: 5em;
    overflow-y: auto;
    line-height: 1.4em;
    max-height: 85%;
}
.article-toc .toc-wrapper{
    position: fixed;
}
.article-toc nav {
    margin-left: 1em;
}
.article-toc h4 {
    margin-left: 0;
}
.article-toc ul {
    margin-bottom: 0;
    padding: 0;
}
.article-toc li {
    list-style: none;
    margin-left: 20px;
    margin-top: 2px;
}
.article-toc li a {
    color: var(--text-color);
    text-decoration: none;
}
.article-toc li.active {
    font-weight: bold;
}
.article-toc li.inactive {
    font-weight: 300;
}
@media screen and (min-width: 100em) {
    .article-toc {
        display: block;
    }
}
.next-post {
    text-align: right;
    float: right;
}
.previous-post {
    float: left;
}
.content pre code {
    white-space: pre;
}
div.highlight pre {
    overflow-x: auto;
}
#page-nav {
    text-align: center;
}
#page-nav a {
    margin: 0 0.2em;
}
#page-nav span {
    margin: 0 0.2em;
}
.next {
    float: right;
    display: inline;
}
.prev {
    float: left;
    display: inline;
}
.current {
    color: var(--text-color);
}

