  const body = document.body;
  const content = document.querySelector('.container.content');
  return {
    bodyOverflow: getComputedStyle(body).overflow,
    bodyHeight: getComputedStyle(body).height,
    contentOverflowY: getComputedStyle(content).overflowY,
    bodyScrollWidth: body.scrollWidth,
    viewportWidth: window.innerWidth,
    horizontalOverflow: body.scrollWidth > window.innerWidth
  };
}

() => {
  const all = Array.from(document.querySelectorAll('*'));
  const overflowing = all.filter(el => {
    const rect = el.getBoundingClientRect();
    return rect.right > window.innerWidth + 2;
  }).map(el => ({ tag: el.tagName, class: el.className, right: el.getBoundingClientRect().right }));
  return overflowing.slice(0, 10);
}

