() => {
  const wrapper = document.querySelector('.wrapper');
  const sidebar = document.querySelector('.sidebar');
  const content = document.querySelector('.container.content');
  return {
    wrapperDisplay: getComputedStyle(wrapper).display,
    wrapperFlexDir: getComputedStyle(wrapper).flexDirection,
    wrapperHeight: getComputedStyle(wrapper).height,
    sidebarPosition: getComputedStyle(sidebar).position,
    sidebarBg: getComputedStyle(sidebar).backgroundColor,
    sidebarWidth: getComputedStyle(sidebar).width,
    contentOverflowX: getComputedStyle(content).overflowX,
    contentOverflowY: getComputedStyle(content).overflowY,
    viewportWidth: window.innerWidth,
  };
}

