() => {
  // Find first sidenote and first code block
  const sn = document.querySelector('.sidenote');
  const code = document.querySelector('.post pre, .post .highlight');
  return {
    snRect: sn ? JSON.stringify(sn.getBoundingClientRect()) : 'none',
    snY: sn ? Math.round(sn.getBoundingClientRect().top + window.scrollY) : 0,
    codeRect: code ? JSON.stringify(code.getBoundingClientRect()) : 'none',
    codeY: code ? Math.round(code.getBoundingClientRect().top + window.scrollY) : 0,
  };
}

() => {
  // Find all sidenotes and check if any overlap with code blocks
  const sidenotes = Array.from(document.querySelectorAll('.sidenote, .marginnote'));
  const codeBlocks = Array.from(document.querySelectorAll('.post .highlight, .post pre'));
  const scrollY = window.scrollY;

  const overlaps = [];
  sidenotes.forEach((sn, i) => {
    const snR = sn.getBoundingClientRect();
    const snTop = snR.top + scrollY;
    const snBot = snR.bottom + scrollY;

    codeBlocks.forEach((cb, j) => {
      const cbR = cb.getBoundingClientRect();
      const cbTop = cbR.top + scrollY;
      const cbBot = cbR.bottom + scrollY;

      // vertical overlap check
      if (snTop < cbBot && snBot > cbTop) {
        overlaps.push({ snIndex: i, cbIndex: j, snTop: Math.round(snTop), cbTop: Math.round(cbTop), cbBot: Math.round(cbBot), snX: Math.round(snR.x), cbRight: Math.round(cbR.right) });
      }
    });
  });
  return overlaps.slice(0, 5);
}

