  label.sidenote-number {
    cursor: default;
  }

  label.marginnote-ind {
    display: inline;
    cursor: default;
  }
}

/* ── Full-width elements ─────────────────────────────────────── */

.fullwidth {
  max-width: 90%;
  clear: both;
}

/* ── Figure shortcode ────────────────────────────────────────── */

figure {
  padding: 0;
  border: 0;
  max-width: 55%;
  margin: 0 0 2em 0;
}

figure.fullwidth {
  max-width: 90%;
}

figcaption {
  float: right;
  clear: right;
  margin-right: -48%;
  margin-top: 0;
  margin-bottom: 0;
  font-size: 0.95rem;
  line-height: 1.5;
  vertical-align: baseline;
  position: relative;
  max-width: 40%;
}

figure.fullwidth figcaption {
  margin-right: 24%;
}

@media (max-width: 760px) {
  figure {
    max-width: 90%;
  }
  figcaption,
  figure.fullwidth figcaption {
    margin-right: 0;
    max-width: none;
    float: none;
  }
}
