() => {
  const sidenotes = [...document.querySelectorAll('.sidenote, .marginnote')];
  const codeBlocks = [...document.querySelectorAll('.post .highlight, .post .code-container')];

  const snRects = sidenotes.map(el => {
    const r = el.getBoundingClientRect();
    const scrollY = window.scrollY;
    return { top: r.top + scrollY, bottom: r.bottom + scrollY, display: el.style.display || getComputedStyle(el).display };
  });

  const cbRects = codeBlocks.map(el => {
    const r = el.getBoundingClientRect();
    const scrollY = window.scrollY;
    return { top: r.top + scrollY, bottom: r.bottom + scrollY, tag: el.tagName, class: el.className };
  });

  // Check for overlaps
  const overlaps = [];
  for (const sn of snRects) {
    for (const cb of cbRects) {
      if (sn.top < cb.bottom && sn.bottom > cb.top) {
        overlaps.push({ sidenote: sn, codeBlock: cb });
      }
    }
  }

  return { sidenoteCount: snRects.length, codeBlockCount: cbRects.length, overlaps };
}

